import {validWorkbookReport,workbookChoices,workbookQuestions,questionnaireLocale} from './innerly-v1-model.mjs';
import {consolidatedComparisonMarkup} from './report-comparison-summary.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=r=>new Date(r.createdAt).toLocaleString(undefined,{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
export function comparisonData(reports,{language,fromId,toId,question=0}={}){
 const valid=reports.filter(validWorkbookReport),code=language||valid[0]?.language||'en';
 const rows=[...new Map(valid.filter(r=>r.language===code).map(r=>[r.id,r])).values()].sort((a,b)=>Date.parse(a.createdAt)-Date.parse(b.createdAt)||a.id.localeCompare(b.id));
 let to=rows.find(r=>r.id===toId)||rows.at(-1),from=rows.find(r=>r.id===fromId)||rows[0];
 if(from&&to&&rows.indexOf(from)>rows.indexOf(to))[from,to]=[to,from];
 const index=Number.isInteger(question)&&question>=0&&question<36?question:0;
 return {rows,language:code,from,to,question:index,changed:from&&to?from.answers.filter((v,i)=>v!==to.answers[i]).length:0};
}
export function comparisonMarkup(reports,selection={}){
 const data=comparisonData(reports,selection),{rows,from,to,question,language,changed}=data;
 if(!rows.length)return '';
 const languages=[...new Set(reports.filter(validWorkbookReport).map(r=>r.language))];
 const options=selected=>rows.map((r,i)=>`<option value="${esc(r.id)}" ${r.id===selected?.id?'selected':''}>${esc(date(r))} · Check-in ${i+1}</option>`).join('');
 const labels=workbookChoices(language),first=Date.parse(rows[0].createdAt),span=Date.parse(rows.at(-1).createdAt)-first;
 const x=r=>span?172+((Date.parse(r.createdAt)-first)/span)*500:422,y=v=>238-v*48;
 const segments=rows.slice(1).map((r,i)=>Number.isInteger(r.answers[question])&&Number.isInteger(rows[i].answers[question])?`<line x1="${x(rows[i])}" y1="${y(rows[i].answers[question])}" x2="${x(r)}" y2="${y(r.answers[question])}"/>`:'').join('');
 const points=rows.filter(r=>Number.isInteger(r.answers[question])).map(r=>`<circle cx="${x(r)}" cy="${y(r.answers[question])}" r="6"><title>${esc(date(r)+': '+labels[r.answers[question]])}</title></circle>`).join('');
 return `<section class="report-comparison" aria-labelledby="comparison-title"><p class="mh-kicker">YOUR RESPONSES OVER TIME</p><h2 id="comparison-title">Notice what has changed.</h2><p>Compare check-ins from the same questionnaire and language. Each point is an actual saved response; days without a check-in have no measurement.</p><div class="comparison-selectors">${languages.length>1?`<label>Question language<select data-compare="language">${languages.map(l=>`<option value="${l}" ${l===language?'selected':''}>${new Intl.DisplayNames(['en'],{type:'language'}).of(l)}</option>`).join('')}</select></label>`:''}<label>Before<select data-compare="fromId">${options(from)}</select></label><label>After<select data-compare="toId">${options(to)}</select></label></div>${rows.length<2?'<p class="history-notice">Save another check-in to see a before-and-after comparison.</p>':`<div class="comparison-summary"><strong>${changed} of 36</strong><span>answers differ between these two reports</span></div>`}<label class="comparison-question">Choose a question to follow<select data-compare="question">${questionnaireLocale(language).dimensions.map((name,d)=>`<optgroup label="${esc(name)}">${workbookQuestions.slice(d*6,d*6+6).map((q,j)=>`<option value="${d*6+j}" ${d*6+j===question?'selected':''}>${d*6+j+1}. ${esc(q.texts[language]||q.texts.en)}</option>`).join('')}</optgroup>`).join('')}</select></label><h3>${esc(workbookQuestions[question].texts[language]||workbookQuestions[question].texts.en)}</h3><div class="comparison-chart" role="region" tabindex="0" aria-label="Response timeline"><svg viewBox="0 0 720 290" role="img" aria-label="Your response frequency over time. Exact answers follow below.">${labels.map((label,i)=>`<text x="158" y="${y(i)+5}" text-anchor="end">${esc(label)}</text><line class="comparison-grid" x1="172" x2="672" y1="${y(i)}" y2="${y(i)}"/>`).join('')}<g class="comparison-line">${segments}</g><g class="comparison-points">${points}</g><text x="172" y="278">${esc(new Date(rows[0].createdAt).toLocaleDateString())}</text>${rows.length>1?`<text x="672" y="278" text-anchor="end">${esc(new Date(rows.at(-1).createdAt).toLocaleDateString())}</text>`:''}</svg></div><p class="history-notice">Higher means a more frequent response, not automatically better health. A helpful habit and a difficulty can move in opposite directions. These are reflection responses, not a clinical progress score.</p><details><summary>Exact dates and responses (${rows.length})</summary><div class="comparison-table"><table><thead><tr><th>Check-in</th><th>Response</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(date(r))}</td><td>${esc(labels[r.answers[question]]||'Not answered')}</td></tr>`).join('')}</tbody></table></div></details>${rows.length>1?`<details><summary>Compare all 36 answers</summary><div class="comparison-table"><table><thead><tr><th>Question</th><th>Before · ${esc(date(from))}</th><th>After · ${esc(date(to))}</th></tr></thead><tbody>${workbookQuestions.map((q,i)=>`<tr class="${from.answers[i]===to.answers[i]?'':'response-changed'}"><th scope="row">${i+1}. ${esc(q.texts[language]||q.texts.en)}</th><td>${esc(labels[from.answers[i]]||'Not answered')}</td><td>${esc(labels[to.answers[i]]||'Not answered')}</td></tr>`).join('')}</tbody></table></div></details>`:''}${rows.length>1?consolidatedComparisonMarkup(from,to):''}</section>`;
}
export function accountHistoryMarkup({localReports,cloud,source='account',config,autoSave=false,selection={},saving=false,status=''}){
 const account=source==='account',reports=account?cloud.reports:localReports;
 return `<section class="mh-history"><p class="mh-kicker">MY REPORTS</p><h1>Your check-ins. Your pace.</h1><div class="history-source" role="group" aria-label="Report location"><button data-history-source="account" aria-pressed="${account}">My account</button><button data-history-source="device" aria-pressed="${!account}">This browser</button></div>${account?`<p>Reports you save to this account are available after signing in on another device.</p>${!cloud.userId?'<div class="history-notice"><p>Sign in to save reports to your account and compare your check-ins.</p><button class="mh-primary" data-cloud-action="signin">Sign in</button></div>':`<div class="history-toolbar"><p>${autoSave?'Auto-save is on for new check-ins in this browser.':'Choose which reports to save, or turn on auto-save for new check-ins.'}</p><button class="mh-secondary" data-cloud-action="autosave">${autoSave?'Turn off auto-save':'Turn on auto-save'}</button><button class="mh-secondary" data-cloud-action="refresh" ${cloud.loading?'disabled':''}>Refresh reports</button></div>${config&&!config.cloudEnabled?'<p class="history-notice">Account storage is being prepared. Your device reports are still available.</p>':''}`}`:'<p>These reports are stored in this browser. Anyone using this browser can open them. Save only your own reports to your account.</p>'}${status?`<p class="history-notice" role="status">${esc(status)}</p>`:''}${cloud.error&&account?`<p class="history-notice" role="alert">${esc(cloud.error)} <button data-cloud-action="refresh">Try again</button></p>`:''}${cloud.loading&&account?'<p role="status">Loading your account reports…</p>':''}${reports.length?`<div class="mh-saved-list">${reports.map(r=>`<article><div class="mh-saved-copy"><span>${esc(date(r))}</span><strong>${r.version==='innerly-workbook-v1'?'36-question check-in':'Earlier check-in'}</strong><small>${esc(new Intl.DisplayNames(['en'],{type:'language'}).of(r.language))} · ${account?'Saved to account':'Saved on this device'}</small></div><div class="mh-saved-actions"><button class="mh-saved-open" ${account?'data-cloud-open':'data-open'}="${esc(r.id)}">View report</button>${!account&&r.version==='innerly-workbook-v1'?`<button data-cloud-save="${esc(r.id)}" ${saving?'disabled':''}>${saving?'Saving…':'Save to account'}</button>`:''}<button class="report-delete-button" ${account?'data-cloud-delete':'data-delete'}="${esc(r.id)}">Delete</button></div></article>`).join('')}</div>`:!cloud.loading?'<p class="mh-empty">Your saved reports will appear here.</p>':''}${account&&cloud.cursor?'<button class="mh-secondary" data-cloud-action="more">Load older reports</button>':''}${comparisonMarkup(reports,selection)}<button class="mh-primary" data-action="new-test">Start a new test →</button></section>`;
}
